 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':800,'height':1300});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base+'/baccarat/index.html');page.add_style_tag(content='main{margin-top:206px}');page.wait_for_function('()=>!!window.CLASSIC');page.evaluate('''()=>{const v=CLASSIC,c=v.controller;c.start();const plans=[[54,61,56,58],[106,113,108,110],[156,159,157,160],[210,217,212,214]],prefix=plans.flat(),s=c.session.state;s.shoe.order=[...prefix,...s.shoe.order.filter(x=>!prefix.includes(x))];s.shoe.cursor=s.shoe.burn=0;for(const a of plans){c.select('player');c.chip(100);c.confirm();c.session.skip();c.next();}v.title();}''');page.wait_for_timeout(5400);page.locator('[data-classic=record]').click();page.wait_for_timeout(150);page.mouse.move(795,1290);page.screenshot(path=str(out/'record-page.png'));page.locator('canvas').screenshot(path=str(out/'record.png'));page.get_by_role('button',name='OK',exact=True).click();page.locator('[data-classic=start]').click();page.locator('[data-classic="bet:player"]').click();page.locator('[data-classic=max]').click();page.wait_for_timeout(300);page.locator('canvas').screenshot(path=str(out/'max.png'));assert page.evaluate('()=>CLASSIC.controller.session.state.bets.player')==5000000;assert page.evaluate('()=>CLASSIC.coins.filter(x=>x.x===100).length')==5;page.locator('[data-classic=min]').click();page.locator('canvas').screenshot(path=str(out/'min.png'));page.locator('[data-classic="chip:1000"]').click();page.locator('[data-classic=clear]').click();page.locator('canvas').screenshot(path=str(out/'clear.png'));assert page.evaluate('()=>Object.keys(CLASSIC.controller.session.state.bets).length')==0
 # Keyboard betting and sound controls remain operable, without canvas-only input.
